{
  "implementation": "def solve(case):
    segments = case['segments']
    n = len(segments)
    names = [s['name'] for s in segments]
    importance = [s['importance'] for s in segments]
    minimum = [s['minimum'] for s in segments]
    capacity = [s['capacity'] for s in segments]
    budget = case['budget']
    sum_min = sum(minimum)
    sum_cap = sum(capacity)
    if budget < sum_min or budget > sum_cap:
        raise ValueError(f"Budget {budget} out of range [{sum_min}, {sum_cap}]")
    allocs = list(minimum)
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = None
        best_val = -1.0
        for i in range(n):
            if allocs[i] < capacity[i]:
                val = importance[i] / (allocs[i] + 1)
                if val > best_val:
                    best_val = val
                    best_idx = i
        if best_idx is None:
            break
        allocs[best_idx] += 1
        remaining -= 1
    total = sum(allocs)
    by_name = {names[i]: allocs[i] for i in range(n)}
    return {"allocations": allocs, "by_name": by_name, "total": total}
